 return result,err
}

// Retain forward documents until overwritten, windows, and every unrelated
// namespace. Tombstone superseded reverse/alias keys so sync cannot revive them.
func clearDerivedEntityKeys(st gitmeta.State) gitmeta.State {
 out := gitmeta.State{Tombstones:append([]gitmeta.Tombstone(nil),st.Tombstones...)}
 removed := map[stateKey]bool{}
 drop := func(target gitmeta.Target,key string) bool {
  if target != projectTarget || (!strings.HasPrefix(key,reverseKeyPrefix) && !strings.HasPrefix(key,aliasKeyPrefix)) { return false }
  id := stateKey{target,key}
  if !removed[id] { out.Tombstones = append(out.Tombstones,gitmeta.Tombstone{Target:target,Key:key}); removed[id]=true }
  return true
 }
 for _,v := range st.Strings { if !drop(v.Target,v.Key) { out.Strings=append(out.Strings,v) } }
 for _,v := range st.Lists { if !drop(v.Target,v.Key) { out.Lists=append(out.Lists,v) } }
 for _,v := range st.Sets { if !drop(v.Target,v.Key) { out.Sets=append(out.Sets,v) } }
 return out
}
